import csv
from collections import defaultdict
from datetime import datetime

def dt(s):
    s = (s or '').strip()
    if not s:
        return None
    for fmt in ('%Y-%m-%d %H:%M:%S', '%Y-%m-%d'):
        try:
            return datetime.strptime(s, fmt)
        except ValueError:
            pass

stats = defaultdict(lambda: [0, 0])
with open('bookstore_orders.csv') as f:
    for r in csv.DictReader(f):
        if r['fulfillment_status'] != 'Delivered':
            continue
        est, act = dt(r['estimated_delivery_date']), dt(r['actual_delivery_date'])
        if est is None or act is None:
            continue
        s = stats[r['carrier_name']]
        s[0] += 1
        if act <= est:
            s[1] += 1

rows = []
for c, (total, ontime) in stats.items():
    rows.append([c, total, ontime, round(ontime / total * 100, 2)])
rows.sort(key=lambda x: -x[3])
with open('carrier-otd.csv', 'w', newline='') as f:
    w = csv.writer(f)
    w.writerow(['CarrierName', 'TotalDelivered', 'OnTimeDelivered', 'OnTimePct'])
    w.writerows(rows)
print(open('carrier-otd.csv').read())
