    return _FILES[f] + str(r + 1)


def legal_moves(fen: str) -> list[str]:
    board, stm, rights = _parse(fen)
    return [_sq(*frm) + _sq(*to) for frm, to in _gen(board, stm, rights)]


def perft(fen: str, depth: int) -> int:
